mapper.update:
UPDATE TimecardInfo SET status=#{status},
lastModifiedOn=now()
WHERE tcId=#{tcId} and empId=#{empId}

mapper.select:
select ifnull(
(select tcId
from TimecardInfo where empId=#{empId} and tcId =#{tcId}
),-1) from
dual;

select ifnull(
(select tcId
from TimecardInfo where empId=#{empId} and
(weekStart between
#{weekStart} and #{weekEnd})
),-1) from dual;

select ifnull(
(select tcId
from TimecardInfo where tcID=#{tcId} and status=#{status}),-1) from dual;

select
tcId,empId,weekStart,weekEnd,totalHours,totalWeekWorkHours,status from
TimecardInfo


		tcId=#{tcId}


		and weekStart=#{weekStart}


		and weekEnd=#{weekEnd}


		and status=#{status}

select tci.tcId,ifnull(weekStart,' ') as weekStart,
ifnull(weekEnd,' ') as weekEnd, ifnull(tci.status,' ') as status,
ifnull(concat(date_format(weekStart,'%d %b'),' to ',date_format(weekend,'%d %b')),' ') WeekPeriod,
ifnull(totalHours,' ') totalHours,ifnull(tci.status,' ')
statusGrid,ifnull((select group_concat(distinct concat(firstName,' ',middleName,' ',lastName)) from 
TimecardApproverDetails tcad, EmployeeInfo ei where tci.tcId=tcad.tcId and ei.empId=tcad.approverId),' ') managerName
from TimecardInfo tci  where tci.empId=#{empId} 


		and tci.status=#{status} 


		and weekStart >=#{weekStart,jdbcType=VARCHAR}


		and weekEnd <=#{weekEnd,jdbcType=VARCHAR};

select ifnull((select tcadId from TimecardApproverDetails
where tcId=#{tcId} and projectId=#{projectId} and approverId=#{approverId}
limit 0,1),-1) from dual

select tcId,empId,weekStart,weekEnd,totalHours,status from
TimecardInfo where empId=#{empId}  


		and tcId=#{tcId} 


		and weekStart >=#{weekStart,jdbcType=VARCHAR}


		and weekEnd <=#{weekEnd,jdbcType=VARCHAR};

select tcId, weekStart, weekEnd, status, totalHours, approverId, projectGroup,empId from (  
select tci.tcId tcId, tci.weekStart weekStart ,tci.weekEnd weekEnd, tci.status status , tci.totalHours totalHours, 
tcad.approverId approverId, tcad.projectID projectId, 
ifnull((select group_concat(tcadsub.projectId) from TimecardApproverDetails tcadsub where 
tcadsub.tcID=tcad.tcId),' ') projectGroup,tci.empId empId
from TimecardApproverDetails tcad, TimecardInfo tci 
where empId=#{empId} and tci.tcId=tcad.tcId 


	and weekStart =#{weekStart,jdbcType=VARCHAR}


	and weekEnd =#{weekEnd,jdbcType=VARCHAR}


	and tci.status in (

			#{item} 

	)  

) as Main group by 1 order by weekStart desc, if(status in ('Pending'),'01',status) ;

select tcId, weekStart, weekEnd, status, totalHours, approverId, projectGroup,empId,empName,searchType from (  
	select tci.tcId tcId, tci.weekStart weekStart ,tci.weekEnd weekEnd, tci.status status , tci.totalHours totalHours, 
	tcad.approverId approverId, tcad.projectID projectId, 
	ifnull((select group_concat(tcadsub.projectId) from TimecardApproverDetails tcadsub where 
	tcadsub.approverId=tcad.approverId and tcadsub.tcID=tcad.tcId),' ') projectGroup,tci.empId empId,
	ifnull((select concat_ws(' ',firstName,middleName,lastName) from EmployeeInfo EI where EI.empId=tci.empId),' ' ) empName,			
	ifnull((select role from RolesInfo,EmployeeInfo EI where tci.empId=EI.empId and EI.designationId=roleId),' ') searchType		
	from TimecardApproverDetails tcad, TimecardInfo tci 
	where approverId=#{empId} and tci.tcId=tcad.tcId 


		and weekStart =#{weekStart,jdbcType=VARCHAR}


		and weekEnd =#{weekEnd,jdbcType=VARCHAR}


		and tci.status in (

				#{item} 

		)  

) as Main group by 1 order by if(status in ('Pending'),'01',status), weekStart desc, tcId;

select tcdd.tcId tcId, tcdd.tcdId tcdId,tcdd.tcddId tcddId, projectId, activityId, location,  tcdd.status status, taskDetails,
group_Concat('$',concat(workingDate,'*',startTime,'*',endTime,'*',tcdd.workingHours)) timecardRowDetails,
ifnull((select projectName from ProjectsInfo PI where PI.projectId= tcdd.projectId),' ') projectName,
ifnull((select activity from ActivitiesInfo PI where PI.activityId= tcdd.activityId),' ') activityName,
ifnull((select location from WorkLocationsInfo PI where PI.workLocationId = tcdd.location),' ') locationName,
convert(sec_to_time(sum(Time_to_sec(workingHours))),char) projectWorkHour		 
 from TimecardDayDetails tcdd, 
TimecardDayInfo tcdi, TimecardInfo tci
where empId=#{empId}  	


	and tcdd.projectId=#{projectId}  



	and tci.tcId=#{tcId} 

and tci.tcId=tcdd.tcId and tcdd.tcId=tcdi.tcId and tcdd.tcdId=tcdi.tcdId and 
tcdd.recordType='Active' group by tcdd.projectId,location,activityId,rowIndex  
order by tcdd.projectId,location,activityId,rowIndex  ;

select tcdd.tcId tcId, Convert(sec_to_time(sum(Time_to_sec(workingHours))), Char) totalProjectWorkHour, tcdd.projectId projectId, ifnull((select projectName from ProjectsInfo PI where PI.projectId=tcdd.projectId),' ') projectName,#{empId} empId, ifnull((select concat(firstName,' ', middleName,' ', lastName) from TimecardApproverDetails tcad, EmployeeInfo ei where tcad.projectId=tcdd.projectId and tcad.tcId=tcdi.tcId and tcad.approverId=ei.empId),' ') as approverName, ifnull((select comments from TimecardApproverDetails tcad, EmployeeInfo ei where tcad.projectId=tcdd.projectId and tcad.tcId=tcdi.tcId and tcad.approverId=ei.empId),' ') as approverComment, ifnull((select tcad.status from TimecardApproverDetails tcad, EmployeeInfo ei where tcad.projectId=tcdd.projectId and tcad.tcId=tcdi.tcId and tcad.approverId=ei.empId),' ') as status from TimecardDayDetails tcdd,TimecardDayInfo tcdi where tcdd.tcId=#{tcId} and tcdd.tcId=tcdi.tcId and tcdd.tcdId=tcdi.tcdId and tcdd.projectId in (
#{item}
) and tcdd.recordType='Active' group by tcdd.projectId;

select tcdd.tcId tcId, tcdd.tcdId tcdId,tcdd.tcddId tcddId, projectId, activityId, location,  tcdd.status status, taskDetails,
group_Concat('$ ',concat(workingDate,'*',startTime,'*',endTime,'*',tcdd.workingHours)) timecardRowDetails,
ifnull((select projectName from ProjectsInfo PI where PI.projectId= tcdd.projectId),' ') projectName,
ifnull((select activity from ActivitiesInfo PI where PI.activityId= tcdd.activityId),' ') activityName,
ifnull((select location from WorkLocationsInfo PI where PI.workLocationId = tcdd.location),' ') locationName,
convert(sec_to_time(sum(Time_to_sec(workingHours))),char) projectWorkHour,
ifnull((select group_concat(if(TI.status='Pending','Y','N')) from TimecardInfo TI 
where TI.weekstart < tci.weekStart order by TI.weekstart desc limit 2),'N,N') prevWeekPendingStat, 
ifnull((select group_concat(if(TI.status='Pending','Y','N')) from TimecardInfo TI 
where TI.weekstart > tci.weekStart order by TI.weekstart asc limit 2),'N,N') nextWeekPendingStat
from TimecardDayDetails tcdd, 
TimecardDayInfo tcdi, TimecardInfo tci
where empId=#{empId}  	


	and tci.tcId=#{tcId} 


	and tci.weekStart >=#{weekStart,jdbcType=VARCHAR}


	and tci.weekEnd <=#{weekEnd,jdbcType=VARCHAR}

and tci.tcId=tcdd.tcId and tcdd.tcId=tcdi.tcId and tcdd.tcdId=tcdi.tcdId and 
tcdd.recordType='Active' group by rowIndex order by rowIndex ;

mapper.update:
UPDATE TimecardDayDetails SET status=#{status},
lastModifiedOn=now()
WHERE tcId=#{tcId} and projectId=#{projectId}

UPDATE TimecardApproverDetails SET status=#{status},comments=#{approverComment},
lastModifiedOn=now()
WHERE tcId=#{tcId} and projectId=#{projectId}
